/**
 * @name Unsafe deserialization
 * @description Deserializing untrusted data using pickle or other unsafe methods can lead to arbitrary code execution
 * @kind path-problem
 * @problem.severity error
 * @id py/unsafe-deserialization
 * @tags security
 *        external/cwe/cwe-502
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module DeserializationConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Use API graphs to find deserialization sinks
    exists(API::CallNode call |
      // pickle.load, pickle.loads, pickle.Unpickler
      call = API::moduleImport("pickle").getMember(["load", "loads", "Unpickler"]).getACall() and
      sink = call.getArg(0)
    )
    or
    exists(API::CallNode call |
      // yaml.load, yaml.unsafe_load
      call = API::moduleImport("yaml").getMember(["load", "unsafe_load"]).getACall() and
      sink = call.getArg(0)
    )
    or
    exists(API::CallNode call |
      // marshal.load, marshal.loads
      call = API::moduleImport("marshal").getMember(["load", "loads"]).getACall() and
      sink = call.getArg(0)
    )
    or
    exists(API::CallNode call |
      // shelve.open
      call = API::moduleImport("shelve").getMember("open").getACall() and
      sink = call.getArg(0)
    )
  }
}

module DeserializationFlow = TaintTracking::Global<DeserializationConfig>;
import DeserializationFlow::PathGraph

from DeserializationFlow::PathNode source, DeserializationFlow::PathNode sink
where DeserializationFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Unsafe deserialization from $@.", source.getNode(), "user input"

/**
 * @name Path traversal in file operations
 * @description Using user-controlled input in file paths can lead to path traversal attacks
 * @kind path-problem
 * @problem.severity high
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // File open operations
    exists(API::CallNode call |
      call = API::moduleImport("builtins").getMember("open").getACall() and
      sink = call.getArg(0)
    )
    or
    // os.path operations that could be used for file access
    exists(API::CallNode call |
      call = API::moduleImport("os").getMember(["open", "chdir", "remove", "rename", "stat"]).getACall() and
      sink = call.getArg(0)
    )
    or
    // shutil operations
    exists(API::CallNode call |
      call = API::moduleImport("shutil").getMember(["copy", "move", "rmtree"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal vulnerability from $@.", source.getNode(), "user input"

/**
 * @name Import manipulation vulnerabilities
 * @description Direct manipulation of sys.modules or use of __import__ with untrusted input can lead to module hijacking
 * @kind path-problem
 * @problem.severity high
 * @id py/import-manipulation
 * @tags security
 *        external/cwe/cwe-470
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module ImportManipulationConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // sys.modules assignment
    exists(API::CallNode call |
      call = API::moduleImport("sys").getMember("modules").getMember("__setitem__").getACall() and
      sink = call.getArg(0)
    )
    or
    // __import__ function with dynamic argument
    exists(API::CallNode call |
      call = API::builtin("__import__").getACall() and
      sink = call.getArg(0)
    )
    or
    // importlib.import_module with dynamic argument
    exists(API::CallNode call |
      call = API::moduleImport("importlib").getMember("import_module").getACall() and
      sink = call.getArg(0)
    )
  }
}

module ImportManipulationFlow = TaintTracking::Global<ImportManipulationConfig>;
import ImportManipulationFlow::PathGraph

from ImportManipulationFlow::PathNode source, ImportManipulationFlow::PathNode sink
where ImportManipulationFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Import manipulation from $@.", source.getNode(), "user input"
